#!/usr/bin/env python3
"""rnv-brand landing script, step 1 of 3: Ship the brand's five faces in engine/fonts/, with their licenses, a guard and font_faces()

The brand's font files: engine/fonts/ (22 woff2 files and 5 OFL licenses), the import guard and font_faces() in engine/brand.py, packaging in pyproject.toml (44.1.0), BRAND_TYPE.md rev 12 and two README notes.

Run it from the root of an rnv-brand checkout (a Codespace works), on the commit
named below. It writes files and commits nothing.

    python3 land_1_*.py --check     # says what it would do, writes nothing
    python3 land_1_*.py             # writes the files
    git add -A && git write-tree           # must print the result tree below
    git commit -m "<the subject above>"

BASE: the commit before it must have tree 4778a03fea4a31c2d85371d6e2ab0513799be388
       (step 1: rnv-brand@aaf34ed; steps 2 and 3: the commit the step before made).
RESULT: after `git add -A`, `git write-tree` prints 730626e5a724b6f8e1224ce5aa80e30ea4dc2460

Every file it writes is checked three ways: the path must hold exactly the blob
it was built against (or be absent, for a new file), or already hold the result,
in which case it is left alone; anything else refuses the whole run before a
byte is written. Run it twice and the second run changes nothing.
"""
import base64, json, subprocess, sys
from pathlib import Path

STEP = "1"
BASE_TREE = "4778a03fea4a31c2d85371d6e2ab0513799be388"
TARGET_TREE = "730626e5a724b6f8e1224ce5aa80e30ea4dc2460"
CHANGES = json.loads(r'''[{"path": "BRAND_TYPE.md", "base": "7f8166e54760f597d6939df6eba2979cd5ff9013", "target": "841ec7a069d1c502229d2c86cc82f34e8884cdcf", "data": ""}, {"path": "README.md", "base": "d7f6c59cc732069cbe4d6ef651a5bc8c720b125b", "target": "aab05e18dd15464130ec26aed1ed081d2d8dff8b", "data": ""}, {"path": "engine/brand.py", "base": "72720340ce06451cb4c47cc1202c4471a6374c30", "target": "5445b99da7d81ae47b9322c791f4e9ce6f6ac075", "data": ""}, {"path": "engine/fonts/OFL-Bricolage-Grotesque.txt", "base": null, "target": "49135ef7afae97fd0746177f0975d23c125f5637", "data": ""}, {"path": "engine/fonts/OFL-Instrument-Serif.txt", "base": null, "target": "a39b7e09b2a12f04fe95fbf9f21a26443f7bef30", "data": ""}, {"path": "engine/fonts/OFL-Inter.txt", "base": null, "target": "40589daa9de8bc96606292ea0be712ff0f0626eb", "data": ""}, {"path": "engine/fonts/OFL-JetBrains-Mono.txt", "base": null, "target": "8f7ed671137e7a27c646ead86f45d5cb4875f459", "data": ""}, {"path": "engine/fonts/OFL-Montserrat.txt", "base": null, "target": "35ae34c4c51f3836b6afcc05a95bd4bced9e7abc", "data": ""}, {"path": "engine/fonts/bricolage-grotesque-latin-ext-opsz-normal.woff2", "base": null, "target": "6e8caa8a6260ad5c2ce28e5966037ed52d0a4ab3", "data": ""}, {"path": "engine/fonts/bricolage-grotesque-latin-opsz-normal.woff2", "base": null, "target": "fcc4eb1eb7ccc8fcacbd60586a61be5e6d4fee13", "data": ""}, {"path": "engine/fonts/instrument-serif-latin-400-italic.woff2", "base": null, "target": "197abca2553c84829217223cdbc6efbe2493d645", "data": ""}, {"path": "engine/fonts/instrument-serif-latin-400-normal.woff2", "base": null, "target": "0ad69719cac6f45ed3057825095b0cdffa7d3c99", "data": ""}, {"path": "engine/fonts/instrument-serif-latin-ext-400-italic.woff2", "base": null, "target": "1f7190917179c3c68972d0eccb6fc7463de46e81", "data": ""}, {"path": "engine/fonts/instrument-serif-latin-ext-400-normal.woff2", "base": null, "target": "0caad588cab430ca20279ca2aee45c8a4629ad3d", "data": ""}, {"path": "engine/fonts/inter-latin-400-normal.woff2", "base": null, "target": "f15b025d666269fb07daf0263e54231481e4289c", "data": ""}, {"path": "engine/fonts/inter-latin-500-normal.woff2", "base": null, "target": "54f0a595dd3c76344a980109e7517ed42416de93", "data": ""}, {"path": "engine/fonts/inter-latin-600-normal.woff2", "base": null, "target": "d1897949fda5c7fc5f04622df43a3fcba5b89d84", "data": ""}, {"path": "engine/fonts/inter-latin-ext-400-normal.woff2", "base": null, "target": "5243e4b2b0274fc97d305e79363e8040975c8775", "data": ""}, {"path": "engine/fonts/inter-latin-ext-500-normal.woff2", "base": null, "target": "2ab7ebf6372b02a3c555eae04f3ada8f1ffeffe1", "data": ""}, {"path": "engine/fonts/inter-latin-ext-600-normal.woff2", "base": null, "target": "bad65d4b7a4e7ded6d25e998a8441fb256de9a79", "data": ""}, {"path": "engine/fonts/jetbrains-mono-latin-400-normal.woff2", "base": null, "target": "585887339efd032b6b715466ae72d86e306bec79", "data": ""}, {"path": "engine/fonts/jetbrains-mono-latin-500-normal.woff2", "base": null, "target": "be878e68fa71bc1f08894c0882d07adbe485ef99", "data": ""}, {"path": "engine/fonts/jetbrains-mono-latin-600-normal.woff2", "base": null, "target": "59c24e7cb8bdff26638068aac0afff3dcbe9b2c1", "data": ""}, {"path": "engine/fonts/jetbrains-mono-latin-700-normal.woff2", "base": null, "target": "3a4e333fc9316f9989e16af6788bf1fc788c7084", "data": ""}, {"path": "engine/fonts/jetbrains-mono-latin-ext-400-normal.woff2", "base": null, "target": "9d97c9b797658435b1e504d4ffc250f8bbbd6c1e", "data": ""}, {"path": "engine/fonts/jetbrains-mono-latin-ext-500-normal.woff2", "base": null, "target": "5cc89b16d9d1c89831a9c3a2dd4d055a920ad3fe", "data": ""}, {"path": "engine/fonts/jetbrains-mono-latin-ext-600-normal.woff2", "base": null, "target": "d5a88f9c17ef069a661dea39e13ed0ebb7b94c69", "data": ""}, {"path": "engine/fonts/jetbrains-mono-latin-ext-700-normal.woff2", "base": null, "target": "6dd7e693b06cc3975c77896a0156f13bdffbaa6d", "data": ""}, {"path": "engine/fonts/montserrat-latin-900-normal.woff2", "base": null, "target": "6dae18c36f76f7e159f2e7de2fd0591c647c136e", "data": ""}, {"path": "engine/fonts/montserrat-latin-ext-900-normal.woff2", "base": null, "target": "6a9ef460532a39422e11ceb93a02cb4516e3f7e2", "data": ""}, {"path": "pyproject.toml", "base": "ff74a3bc6812330f03a25d8e4c6285d02ed61511", "target": "cbd60fe7dd63e79c12c9aefd0eddf888dc473a35", "data": ""}]''')

def git(*args, data=None):
    r = subprocess.run(["git", *args], input=data, capture_output=True)
    if r.returncode:
        sys.exit(f"REFUSED: git {' '.join(args)} failed: {r.stderr.decode().strip()}")
    return r.stdout.decode().strip()

def blob_of(path):
    """The blob hash git would store for this file today, filters applied; None if absent."""
    return git("hash-object", "--", path) if Path(path).is_file() else None

def main():
    check = "--check" in sys.argv
    top = git("rev-parse", "--show-toplevel")
    if Path(top).resolve() != Path.cwd().resolve():
        sys.exit(f"REFUSED: run this from the repository root, {top}")
    if not Path("engine/brand.py").is_file() or not Path("BRAND_COLORS.md").is_file():
        sys.exit("REFUSED: this is not an rnv-brand checkout")
    head_tree = git("rev-parse", "HEAD^{tree}")
    if head_tree != BASE_TREE:
        sys.exit(f"REFUSED: HEAD's tree is {head_tree[:8]}, and step {STEP} was built on {BASE_TREE[:8]}. "
                 f"Land the steps in order, each committed, on rnv-brand@aaf34ed. Nothing written.")
    todo, done, bad = [], [], []
    for c in CHANGES:
        now = blob_of(c["path"])
        if now == c["target"]:
            done.append(c["path"])
        elif now == c["base"]:
            todo.append(c)
        else:
            bad.append(f'{c["path"]}: holds {str(now)[:8]}, expected {str(c["base"])[:8]} (base) or {str(c["target"])[:8]} (result)')
    if bad:
        sys.exit("REFUSED, nothing written. These paths are in neither the state this step was built on nor its result:\n  "
                 + "\n  ".join(bad))
    print(f"step {STEP}: {len(todo)} to write, {len(done)} already applied, of {len(CHANGES)} paths")
    for c in todo:
        print(("  would write " if check else "  write ") + c["path"])
    if check:
        print("--check: nothing written."); return
    for c in todo:
        p = Path(c["path"])
        if c["target"] is None:
            p.unlink(); continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(base64.b64decode(c["data"]))
        if blob_of(c["path"]) != c["target"]:
            sys.exit(f'FAILED after writing {c["path"]}: its blob is not {c["target"][:8]}. Run `git checkout -- .` and report this.')
    others = int(git("ls-tree", "-r", "--name-only", "HEAD").count("\n")) + 1 - sum(1 for c in CHANGES if c["base"])
    print(f"every written file checked against its result blob. Left alone: the other {others} tracked files.")
    print(f"next: git add -A && git write-tree   -> must print {TARGET_TREE}")

if __name__ == "__main__":
    main()
